import itertools

def is_f(r, s):
    for x, y in zip(r, s):
        if abs(x - y) > 1:
            return False
    return True

def solve_for_n(n):
    elements = list(itertools.permutations(range(1, n + 1)))
    m = len(elements)
    adj = [0] * m
    for i in range(m):
        for j in range(m):
            if i != j and is_f(elements[i], elements[j]):
                adj[i] |= (1 << j)

    max_size = 0
    def backtrack(index, current_set_mask, current_size):
        nonlocal max_size
        if index == m:
            if current_size > max_size:
                max_size = current_size
            return

        if current_size + (m - index) <= max_size:
            return

        # Try including elements[index]
        if not (adj[index] & current_set_mask):
            backtrack(index + 1, current_set_mask | (1 << index), current_size + 1)

        # Try excluding elements[index]
        backtrack(index + 1, current_set_mask, current_size)

    backtrack(0, 0, 0)
    return max_size

print(f"n=2: {solve_for_n(2)}")
print(f"n=4: {solve_for_n(4)}")

