def get_mis_rows(n):
    elements = list(itertools.permutations(range(1, n + 1)))
    m = len(elements)
    adj_list = [set() for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if is_f(elements[i], elements[j]):
                adj_list[i].add(j)
                adj_list[j].add(i)

    max_size = 0
    best_set = []

    def mis(p, current_set):
        nonlocal max_size, best_set
        if not p:
            if len(current_set) > max_size:
                max_size = len(current_set)
                best_set = list(current_set)
            return

        if len(current_set) + len(p) <= max_size:
            return

        v = max(p, key=lambda x: len(adj_list[x] & p))

        # Case 1: v is in the MIS
        mis(p - {v} - adj_list[v], current_set + [elements[v]])
        # Case 2: v is not in the MIS
        mis(p - {v}, current_set)

    mis(set(range(m)), [])
    return best_set

print(get_mis_rows(4))

